# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
from author_batch200_root_psych_a import G,H
D=G+[['近代以 psyche + 希腊 delos／deloun 构词','心灵 + 显现、使显露'],['英语 psychedelic','改变感知的；由此联想到的迷幻视觉与音乐风格']]
M=G+[['近代 psycho- + 测量词素 metr-','心理 + 测量'],['英语 psychometric／psychometrics','心理测量的／心理测量学']]
PAN=G+[['pan-“全部” + 心灵相关构词；近代欧洲哲学术语','把心灵或体验的基本性质理解为普遍存在'],['英语 panpsychism','泛心论']]
WC=[
E('psychedelic','/ˌsaɪkəˈdelɪk/','迷幻的；能引起明显感知变化的；迷幻风格的','颜色、图案或声音仿佛变形流动，让人联想到被改变的感知状态。','由 psyche“心灵”与希腊 delos／deloun“显现、使显露”构成；Humphry Osmond 在20世纪提出这一英语术语。',D,'psychedelic 最初与改变感知的物质相关，后来扩展到浓烈色彩、旋转图案和特定音乐风格。psychedelic poster 只是在描述海报风格，不能据此推断创作者使用过什么物质。词源中的“显露心灵”是命名想法，不是科学结论。','psychedelic colours；psychedelic art；psychedelic music。','psychoactive 的范围更广，指影响心理过程；psychedelic 指更特定的感知变化类别或由此衍生的艺术风格。',('The poster uses swirling shapes and psychedelic colours.','海报使用旋转般的形状和迷幻色彩。'),('The band experimented with psychedelic sounds.','这支乐队尝试了迷幻风格的音色。'),sources=['https://www.etymonline.com/word/psychedelic','https://www.merriam-webster.com/dictionary/psychedelic','https://en.wiktionary.org/wiki/psychedelic']),
E('psychedelia','/ˌsaɪkəˈdiːliə/','迷幻文化；迷幻艺术、音乐和相关事物的统称','把那些流动的图案、鲜艳衣饰和实验性的声音放在一起，看成一种文化景象。','psychedelic 对应 -ia 的集合名词形式，不是把每一种物品单独命名。',H(D,'英语 psychedelic → psychedelia','迷幻的 → 迷幻文化与相关事物的统称'),'an exhibition of psychedelia 可能展示海报、唱片封套、服装等。这个名词经常指20世纪特定文化潮流，也可以指后来借用这种风格的作品。它通常作为不可数的整体概念使用。','1960s psychedelia；an exhibition of psychedelia；influenced by psychedelia。','psychedelic 是形容词，也可作物质类别名词；psychedelia 主要把文化、风格与相关作品作为整体来谈。',('The exhibition traces the visual history of psychedelia.','展览梳理了迷幻文化的视觉历史。'),('The album blends folk melodies with elements of psychedelia.','这张专辑把民谣旋律与迷幻风格元素融合在一起。'),sources=['https://www.etymonline.com/word/psychedelic','https://www.collinsdictionary.com/dictionary/english/psychedelia']),
E('psychoactive','英 /ˌsaɪkəʊˈæktɪv/；美 /ˌsaɪkoʊˈæktɪv/','影响心理活动的；作用于意识、情绪等心理过程的','一种物质进入身体后，会改变清醒程度、情绪、感知或其他心理活动。','psycho-“心理” + active“起作用的”，把作用范围指向心智。',G+[['英语 psycho- + active → psychoactive','心理 + 起作用的 → 影响心理过程的']],'咖啡因也属于 psychoactive substance，因为它会影响清醒和注意状态。这个词是作用性质的分类，不等于“非法物质”，也不自动表示会产生幻觉。不同物质的具体作用差别很大。','a psychoactive substance；psychoactive effects；a psychoactive compound。','psychoactive 是较大的范围；psychedelic 是其中更特定的类别名称，不能互换。',('Caffeine is a psychoactive substance.','咖啡因是一种会影响心理活动的物质。'),('The report describes the compound’s psychoactive effects.','报告描述了这种化合物对心理活动的影响。'),sources=['https://www.cancer.gov/publications/dictionaries/cancer-terms/def/psychoactive-substance','https://en.wiktionary.org/wiki/psychoactive']),
E('psychosomatic','英 /ˌsaɪkəʊsəˈmætɪk/；美 /ˌsaɪkoʊsəˈmætɪk/','身心相关的；心理因素参与的身体症状或疾病的','把心理和身体之间那条双向联系看见：情绪与压力可能影响真实的身体体验。','psycho-“心理” + somatic“身体的”，后者接希腊 soma“身体”。',G+[['psycho- 与 somatic 并列组合 → psychosomatic','心理 + 身体 → 身心相互作用的']],'psychosomatic symptoms 不是“装出来的症状”。这个词讨论心理因素怎样参与身体症状的发生、维持或加重，也可广泛说身心互动。具体原因要靠评估，不能因为一次检查没发现原因，就直接认定症状全是心理造成的。','psychosomatic symptoms；psychosomatic medicine；a psychosomatic interaction。','psychosomatic 关注身心联系；imaginary 说不存在或想象的。二者不能画等号。',('The lecture explains the interaction between stress and psychosomatic symptoms.','讲座解释了压力与身心相关症状之间的相互作用。'),('Psychosomatic does not mean that the person is pretending.','身心相关并不意味着当事人在假装。'),sources=['https://dictionary.apa.org/psychosomatic','https://en.wiktionary.org/wiki/psychosomatic']),
E('panpsychism','/pænˈsaɪkɪzəm/','泛心论','尝试用一种哲学想法解释意识：心灵或体验的某种基本性质，也许普遍存在于自然界。','pan-“全部”与 psych-“心灵”相接，再加 -ism；与近代拉丁语、德语相关哲学术语同族。',PAN,'panpsychism 不必主张每块石头都像人一样会思考、会说话。不同版本对“基本体验”怎样存在、怎样与复杂意识相连，有不同回答。这里是在命名一种哲学立场，不是报告已经完成的科学证明。','defend panpsychism；an argument for panpsychism；debates about panpsychism。','panpsychism 把心灵或体验看作普遍的基本性质；pantheism 讨论神与世界的关系，两者不是同一个词或同一种主张。',('The seminar examined arguments for and against panpsychism.','研讨课考察了支持和反对泛心论的论证。'),('Her version of panpsychism does not claim that stones think like humans.','她所主张的泛心论并不认为石头像人一样思考。'),sources=['https://plato.stanford.edu/entries/panpsychism/','https://en.wiktionary.org/wiki/panpsychism']),
E('panpsychist','/pænˈsaɪkɪst/','泛心论者；持泛心论立场的','认为意识不能只靠突然冒出来解释，因而尝试把基本体验放进自然界底层的一位思想者。','与 panpsychism 对应的 -ist 人员或立场名称。',H(PAN,'英语 panpsychism → panpsychist','泛心论 → 泛心论者、泛心论的'),'a panpsychist philosopher 是持泛心论立场的哲学家；a panpsychist view 是这样的观点。不同泛心论者并不一定同意所有细节，不能把这个称呼当成一套人人一致的教义。','a panpsychist philosopher；a panpsychist account of consciousness。','panpsychist 是理论立场的称呼，不等于 psychic，也不表示这个人声称自己能通灵。',('The panpsychist asked how simple forms of experience might relate to human consciousness.','这位泛心论者追问，简单形式的体验可能怎样与人的意识相联系。'),('The book compares physicalist and panpsychist accounts of the mind.','这本书比较了物理主义与泛心论对心灵的解释。'),sources=['https://www.merriam-webster.com/dictionary/panpsychist','https://plato.stanford.edu/entries/panpsychism/']),
E('metempsychosis','美 /məˌtempsɪˈkoʊsɪs/','灵魂转生；灵魂移入另一身体的观念〔书面〕','在某些信仰或故事里，身体死去后，灵魂又进入另一个人的或动物的身体。','希腊 meta-“变化” + en-“进入”与 psyche“灵魂”组成相关词，再经晚期拉丁语进入英语；en- 在 p 前出现 em-。',[['希腊 psyche + en-／meta- → metempsychosis','灵魂 + 进入、变化 → 灵魂转入另一身体'],['晚期拉丁 metempsychosis → 英语 metempsychosis','灵魂转生这一观念']],'这个长词常见于哲学、宗教史或文学讨论。它描述的是灵魂转生的思想，不是临床的 psychosis。把末尾看作现代“精神病性症状”再往前硬接，会完全误解这个古老构词。','the doctrine of metempsychosis；a belief in metempsychosis。','reincarnation 是更常见的转生说法；metempsychosis 更书面，突出灵魂从一具身体移到另一具身体。',('The lecture explored the doctrine of metempsychosis in ancient philosophy.','讲座探讨了古代哲学中的灵魂转生学说。'),('Metempsychosis becomes a recurring theme in the novel.','灵魂转生成为小说中反复出现的主题。'),sources=['https://www.etymonline.com/word/metempsychosis','https://www.merriam-webster.com/dictionary/metempsychosis']),
E('psychopomp','英 /ˈsaɪkəʊpɒmp/；美 /ˈsaɪkoʊpɑːmp/','引导亡灵的神灵或角色〔神话、宗教与文学用语〕','把亡灵想成旅人，这个角色负责带它走向死后的世界。','希腊 psyche“灵魂” + pompos“引导者、护送者”构成 psychopompos，经拉丁等借入形式成为英语 psychopomp。',[['希腊 psyche；pompos','灵魂；引导者、护送者'],['希腊 psyche + pompos → psychopompos','灵魂 + 引导者 → 引导亡灵的角色'],['拉丁 psychopompus → 英语 psychopomp','亡灵的引路者']],'神话中负责护送亡灵的角色可以被称作 psychopomp；它不必是审判者，也不必是造成死亡的人。文学分析也会用这个词描述承担类似引路作用的角色。词尾 pomp 在这里不是英语“排场”。','serve as a psychopomp；the role of a psychopomp。','psychopomp 重点是引路、护送；a judge of the dead 重点是审判亡者，两种功能可能由不同角色承担。',('In the myth, the god acts as a psychopomp for the souls of the dead.','在这个神话中，那位神为亡者的灵魂引路。'),('The critic interprets the boatman as a psychopomp.','评论者把那位船夫解读为引导亡灵的角色。'),sources=['https://www.etymonline.com/word/psychopomp','https://en.wiktionary.org/wiki/psychopomp']),
E('psychoticism','英 /saɪˈkɒtɪsɪzəm/；美 /saɪˈkɑːtɪsɪzəm/','精神质〔艾森克人格模型等研究中的维度名〕','问卷把某些冷漠、冲动、不顺从等倾向放到一条维度上比较，这条维度有这个历史名称。','psychotic + -ism 形成研究术语；它的技术含义不能只按 psychotic 的临床义相加理解。',G+[['英语 psychotic + -ism → psychoticism','精神健康相关词形 → 特定人格模型中的维度名称']],'艾森克人格理论中的 psychoticism，是该模型的一项人格维度。某个量表得分高，不等于直接确诊 psychosis；同名指标在不同工具中也应看具体定义。学习这个词最重要的是先认出它所处的研究框架。','a psychoticism score；the psychoticism dimension；a measure of psychoticism。','psychoticism 是特定测量模型里的构念；psychosis 是症状状态。名字相近，不代表两者能直接替换。',('The study reports scores on the psychoticism dimension.','研究报告了精神质这一人格维度上的得分。'),('A psychoticism score should be interpreted within the model that produced it.','精神质得分应当放回产生它的模型中解释。'),sources=['https://dictionary.apa.org/psychoticism','https://www.collinsdictionary.com/dictionary/english/psychoticism']),
E('psychometric','/ˌsaɪkəˈmetrɪk/','心理测量的','想把记忆、能力、态度等看不见的东西，用有规则的题目和数据来估计。','psycho-“心理” + metric“测量的”，最终接希腊 metron“尺度”。',M,'a psychometric test 是按一定测量原则设计的心理测验；psychometric properties 指它的测量表现，如结果是否稳定、是否真在测所说的东西。分数是工具给出的估计，不是把一个人的全部价值测出来。','psychometric testing；a psychometric test；psychometric properties。','psychometric 不等于 psychic。前者通常谈测量方法，后者在日常语境中可能指所谓超感知能力。',('The researchers examined the questionnaire’s psychometric properties.','研究者检验了这份问卷的心理测量学表现。'),('The course explains how psychometric tests are designed.','课程解释了心理测验是怎样设计的。'),sources=['https://www.apa.org/topics/testing-assessment-measurement','https://en.wiktionary.org/wiki/psychometric']),
E('psychometrics','/ˌsaɪkəˈmetrɪks/','心理测量学','不仅让人答题，还研究：这套题能测到什么，误差有多大，不同人的分数能否公平比较。','psycho-“心理”与 -metrics“测量领域”组合；结尾虽有 s，表示学科时通常按单数处理。',M,'psychometrics 研究心理、教育和行为科学中的量化测量方法，常涉及题目、问卷与统计模型。它不只是发一份测试卷，再把分数加起来；还要检查测量是否可靠、解释是否有根据。','research in psychometrics；a course in psychometrics；psychometrics is。','psychometric 是形容词；psychometrics 是学科名。它与“接触物品就知道其历史”的 psychometry 义项不同。',('Psychometrics is central to the design of reliable assessments.','心理测量学对于设计可靠的评估工具十分重要。'),('She studied psychometrics to understand how test scores should be interpreted.','她学习心理测量学，以理解测试分数应该怎样解释。'),sources=['https://www.psychometricsociety.org/what-psychometrics','https://www.merriam-webster.com/dictionary/psychometrics']),
E('psychometry','英 /saɪˈkɒmətri/；美 /saɪˈkɑːmətri/','触物占知的说法；心理测量〔后一义较少见〕','一种用法声称：手碰到旧物，就能感知它或主人过去的故事；另一种旧用法则说心理测量。','psycho-“心灵” + -metry“测量”；相同构词在历史上形成了不同使用方向。',G+[['近代 psycho- + -metry → psychometry','心灵 + 测量'],['英语的两类用法','所谓触物感知；也用于心理测量']],'小说中的 psychometry 常是接触物体获得隐秘信息的能力，这属于故事设定或超常主张。另一些文献把 psychometry 用作心理测量的名称。现代说科学测量领域，psychometrics 通常更不容易引起歧义。','claim an ability in psychometry；psychometry in fiction。','不能因为词里有 -metry，就认定每一种 psychometry 主张都经过科学验证；也不能把该词的所有历史用法一概归为占卜。',('In the novel, psychometry allows the detective to glimpse an object’s past.','小说设定中，触物感知能力让侦探看到物品过去的片段。'),('The dictionary also records an older use of psychometry for psychological measurement.','词典也记录了 psychometry 用来表示心理测量的较旧用法。'),sources=['https://www.merriam-webster.com/dictionary/psychometry']),
]
